query Query($where: PurchaseOrderStatusWhereInput, $orderBy: [PurchaseOrderStatusOrderByInput!], $first: Int, $after: String) {
  status:purchaseOrderStatus(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        name
        externalId
      }
    }
  }
}

data.variablesTransform:
