data.query:
query Query(
  $po: PurchaseOrderWhereInput,
  $product: ProductWhereInput,
  $supplier: SupplierWhereInput,
  $unit: UnitWhereInput,
  $facility: FacilityWhereInput
) {
  po:purchaseOrder(where: $po) {
    edges {
      node {
        id
        externalId
        number
        purchaseOrderTypeId
        customData
        note
        lines {
          edges {
            node {
              id
              customData
              code
              receiptLines {
                total
              }
            }
          }
        }
        receipts {
          total
        }
      }
    }
  }
  product(where: $product) {edges{node{
    id
    externalId
    productTypeId
    strategies(where:{active:{_eq:true}}){edges{node{
      id
      active
      primary
      name
      facilityId
      facility {
        externalId
      }
      strategyProcesses(where:{final: {_eq: true}active:{_eq:true}}){edges{node{
        id
        active
        code

      }}}
    }}}
  }}}
  supplier(where:$supplier){edges{node{
    id externalId
  }}}
  unit(where:$unit){edges{node{id}}}
  facility(where:$facility){edges{node{id externalId}}}
}

data.variablesTransform:
{
  "msg": {
    "create": {
      "integrationId": $state.context.REQUEST.DATA.integration.id,
      "modelId": $state.context.REQUEST.DATA.model.id,
      "message": $state.context.REQUEST.DATA.model.name 
        & " with ID: "
        & $state.context.REQUEST.DATA.id
        & " failed to return results from SuiteQL query",
      "typeId": "Failure"
    }
  }
}

{
  "msg": {
    "create": {
      "integrationId": $state.context.REQUEST.DATA.integration.id,
      "modelId": $state.context.REQUEST.DATA.model.id,
      "message": $state.context.REQUEST.DATA.model.name 
        & " with ID: "
        & $state.context.REQUEST.DATA.id
        & " must be in 'Released' status for synchronization with Fuuz.",
      "typeId": "Failure"
    }
  }
}

data.transform:
(
  $failI := $leftAntiJoin( 
    [$state.context.REMOTE.trx[itemtype!='OthCharge' and mainline='F'].item.{
      "id": $string($)
    }], 
    [product.edges.node[
      productTypeId!='OthCharge' and $not($isNilOrEmpty(strategies.edges.node.strategyProcesses.edges.node))
    ]], 
    'id', 'externalId'
  );
  $failC := $leftAntiJoin( 
    [$state.context.REMOTE.trx[itemtype='OthCharge' and mainline='F'].item.{
      "id": $string($)
    }], 
    [product.edges.node[productTypeId='OthCharge']], 
    'id', 'externalId'
  );
  $failS := $leftAntiJoin( [$state.context.REMOTE.trx.entity.{
    "id": $string($)
  }], [supplier.edges.node], 'id', 'externalId');


  $failU := $leftAntiJoin( [$state.context.REMOTE.trx.units[mainline='F'].{
    "id": $string($)
  }], [unit.edges.node], 'id', 'id');

   $failF := $leftAntiJoin( [$state.context.REMOTE.trx.location.{
    "id": $string($)
  }], [facility.edges.node], 'id', 'externalId');

  {
    "LOCAL": {
      "fztrx": po.edges.node,
      "product": product.edges.node,
      "supplier": supplier.edges.node,
      "facility": facility.edges.node,
      "failP": $append($failI,$failC),
      "failS": $failS,
      "failU": $failU,
      "failF": $failF
    }
  } 

)

